export const contractItems = (
    id: string,
 signal?: AbortSignal
) => {


      return apiMutator<ContractItemResponse[]>(
      {url: `/api/v1/contracts/${id}/items`, method: 'GET', signal
    },
      );
    }




export const getContractItemsQueryKey = (id: string,) => {
    return [
    `/api/v1/contracts/${id}/items`
    ] as const;
    }


export const getContractItemsQueryOptions = <TData = Awaited<ReturnType<typeof contractItems>>, TError = unknown>(id: string, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof contractItems>>, TError, TData>>, }
) => {

const {query: queryOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getContractItemsQueryKey(id);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof contractItems>>> = ({ signal }) => contractItems(id, signal);





   return  { queryKey, queryFn, enabled: id !== null && id !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof contractItems>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

